function UIHomeMainChapterNode:FillMainChapter()
    kTool.SetActive(self.NewMarkNode, false)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2)
    --未解锁直接退出
    if not isUnlock then
        return
    end

    local curChapterId, isAllPass = QuestConfMgr:GetInstance():GetCurChapterId()
    --所有主线章节都打通了
    if isAllPass then
        kTool.SetActive(self.OverNode, true)
        kTool.SetActive(self.LockTxtChapterNum, false)
    else
        kTool.SetActive(self.OverNode, false)
        kTool.SetActive(self.LockTxtChapterNum, true)

        local curQuestId = QuestConfMgr:GetInstance():GetCurNeedQuestId()
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(curQuestId)
        if vo then
            local isUnlockQuest = QuestConfMgr:GetInstance():IsUnlockQuest(curQuestId)
            local isUnlockChapter, err = QuestConfMgr:GetInstance():IsUnlockChapter(vo.chapter)
            CfUtils.FillText(self.LockTxtChapterNum, vo.label)

            local status = 2 
            if isUnlockChapter and isUnlockQuest then
                status = 1
            else
            end
            CfUtils.SetUISwitchImage(self.BtnBg, status)
            
            --kTool.SetActive(self.NewMarkNode, checkNumber(CfUtils.GetLocalData("MainChapterNew")) == 1)
        end
    end

    GameUtils.BindRedPoint(Constants.RedPointConst.MainQuest, self.AnimRoot, true, nil, function(node)
        local go = GameUtils.GetRedPointGo(self.AnimRoot)

        local isCanDraw = QuestConfMgr:GetInstance():IsHasChapterRewardDraw() or (checkNumber(node.pointNum) > 0)
        local isHasCanDrawReward = QuestConfMgr:GetInstance():IsHasCanDrawChapterReward()
        if go then
            CfUtils.SetActive(go, isCanDraw or isHasCanDrawReward)
        end

        if isCanDraw then
            kTool.SetActive(self.NewMarkNode, false)
        end
    end)

    self:FillTaskInfo()    
end

--任务信息
function UIHomeMainChapterNode:FillTaskInfo()
    local data = questComponent:GetCurTaskInfo()
    if not data then
        return
    end
    
    local isHaveTask = checkNumber(data.id) > 0 
    CfUtils.SetActive(self.DescGroup, isHaveTask)
    if isHaveTask then
        local curQuestId = QuestConfMgr:GetInstance():GetCurNeedQuestId()
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(curQuestId)
        if checkNumber(vo.task) > 0 then
            local taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(vo.task)
            local isCanDraw = QuestConfMgr:GetInstance():IsMainTaskCanDraw(curQuestId)
            CfUtils.SetActive(self.ImgGet , isCanDraw)

            local curCount = 0
            if checkNumber(taskVo.taskContentType) == Constants.TaskType.Submittals then
                curCount = GoodsUtils.GetThingNo(taskVo.taskContentId)
            else
                curCount = data.progress
            end

            local str = ""
            if isCanDraw then
                str = localize("_desc_<color=#ea3eaa>(_num1_/_num2_)</color>", {_desc_ = taskVo.taskTitle, _num1_ = curCount, _num2_ = taskVo.taskContenNum})
            else
                str = localize("_desc_(_num1_/_num2_)", {_desc_ = taskVo.taskTitle, _num1_ = curCount, _num2_ = taskVo.taskContenNum})
            end
            local scr = CfUtils.GetLuaScr(self.MaskText, "Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode")
            if scr then
                scr:Refresh(str, isCanDraw)
            end
            --CfUtils.FillText(self.TxtDesc, str)
        else
            CfUtils.SetActive(self.DescGroup, false)
        end
    end
end

function UIHomeMainChapterNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIHomeMainChapterNode